  "m1037": "Linked tasks",
  "m1038": "Link up to",
  "m1039": "tasks. Inherit their persistent blackboards, asset scopes, and related traffic live in read-only mode. The new task writes to its own blackboard.",
  "m1040": "Link company asset scopes",
  "m1041": "At creation, existing assets of selected companies are added as test assets. Domains, IPs, CIDR, ICP, and company keywords provide scope context to the Agent. This does not automatically create intents or override execution objectives.",
  "m1042": "Task asset block / allow rules (optional)",
  "m1043": "Applies only to this task, not global rules. Block rules (including global ones) are checked first; any match prohibits testing. If no block matches and task allow rules exist, an allow rule must match. Without allow rules, no allowlist applies.",
  "m1044": "LLM profile chain",
  "m1045": "Failover follows list order. The first profile is current; only an explicit insufficient-quota result advances to the next.",
  "m1046": "Advanced settings",
  "m1047": "Timeout · Heartbeat · First intent",
  "m1048": "Task timeout (minutes, optional)",
  "m1049": "Blank = no limit",
  "m1050": "At the deadline, graceful wrap-up begins: agents write back and the planner makes its final assessment. The task ends with timeout status.",
  "m1051": "Planner heartbeat (minutes)",
  "m1052": "Default: 10",
  "m1053": "If this interval passes since the last planning round or task start without another trigger, a planning round starts automatically to recover stalls and supervise running Workers. Minimum: 10 minutes.",
  "m1054": "Dispatch first intent directly (description + objectives)",
  "m1055": "On creation, dispatch the description and objectives as one intent so a Worker starts without waiting for initial planning. The planner evaluates and supplements the result afterward. Recommended for CTF-like scenarios often solved by one Worker. When disabled, planning precedes execution.",
  "m1056": "Asset coverage features",
  "m1057": "Enabled by default: calculate and show test coverage, display progress on the graph, and accumulate test scope automatically. When disabled, coverage and graph progress are hidden and Agents do not receive scope tools. Linked company asset scopes are unaffected.",
