  "m1392": "Proxy (optional)",
  "m1393": "Only outbound LLM requests use this proxy. Supports HTTP/HTTPS/SOCKS5 and credentials (e.g. socks5://user:pass@host:port; URL-encode special password characters). Blank means direct connection.",
  "m1394": "Custom session header (optional)",
  "m1395": "For example, x-session-id (blank = do not send)",
  "m1396": "When a header name is set, every request includes this HTTP header with the value automatically set to",
  "m1397": "the current session ID",
  "m1398": "(chat sessions such as conv-12, Workers such as exp3-worker-i87). For gateways using session headers for prompt caching or sticky routing. Stable across turns within a session and distinct across sessions. Blank disables it.",
  "m1399": "Set ({p0}); leave blank to keep unchanged",
  "m1400": "Per-second rate limit",
  "m1401": "Per-minute rate limit",
  "m1402": "Context window (K)",
  "m1403": "Rate limit 0 = unlimited, shared by all Agents. Context window is in K (thousand tokens): 0 defaults to 200K; maximum 1000 (1M). Setting it too high prevents compression from triggering.",
  "m1404": "Rotation priority",
  "m1405": "Higher numbers are selected first. The active profile is always first regardless of this value. Equal-priority profiles take turns leading to share quota usage.",
  "m1406": "When enabled, this profile is excluded from failover but can still be explicitly selected by Agents or tasks. Useful for expensive profiles reserved for a particular Agent.",
  "m1407": "Streaming output",
  "m1408": "Enabled by default: SSE streaming provides live progress and token counts. Disabled: stream:false returns the full response at once, avoiding faulty gateway SSE implementations such as empty frames or lost reasoning fields, but without live progress.",
  "m1409": "Streaming output",
  "m1410": "Output limit · Max tokens",
  "m1411": "Maximum tokens generated per reply, sent with each request. 0 (default) lets ScopeWeaver choose: agent turns send 32768, direct Anthropic one-shot calls use 8192, and native Ollama applies its own default. This differs from the context window, which is total model capacity used locally to calculate compression thresholds. Too small a limit can cut off reasoning before any answer is produced.",
  "m1412": "Limit field name",
  "m1413": "Thinking toggle · thinking.type",
  "m1414": "Controls whether the thinking field is sent. Omit sends no field for models that do not support it, such as MiniMax; Off sends disabled; On sends enabled; Adaptive sends adaptive, where the model decides how much to think, as Claude 5.5 models do. Independent of the effort setting below.",
  "m1415": "Reasoning effort · reasoning_effort",
  "m1416": "Independent effort level (OpenAI reasoning_effort / Anthropic output_config.effort). Some APIs enable reasoning using effort alone without a thinking field, so effort can be set separately.",
