  "m2591": "<title>Acme Admin · Console",
  "m2592": "Confirmed access to the admin console.",
  "m2593": "Finding f-6 recorded and linked to g1 (proves)",
  "m2594": "Default admin credentials confirmed; objective 1 met.",
  "m2595": "search?q= places q in the result title. First add a single quote to check errors.",
  "m2596": "Signs of MSSQL error-based injection.",
  "m2597": "Injection confirmed; 4 databases enumerated.",
  "m2598": "Finding f-1 recorded",
  "m2599": "SQL injection confirmed.",
  "m2600": "/v1/orders?id= uses sequential numeric IDs, a typical IDOR surface. Fetch our own order, then change the ID to check another user's order.",
  "m2601": "Our own order; normal response.",
  "m2602": "{ \"order_id\":1002, \"user_id\":77, \"amount\":1299, \"phone\":\"138****6021\", \"address\":\"Chaoyang District, Beijing ****\" }",
  "m2603": "Another user's order, including phone/address, is readable without ownership checks.",
  "m2604": "Finding f-2 recorded",
  "m2605": "Traversing IDs to assess the exposed data volume. No export yet to avoid triggering interception rules.",
