  "m0011": "이용 안내",
  "m0012": "로그인 중…",
  "m0013": "ScopeWeaver 이용 안내 및 면책 조항",
  "m0014": "버전 1.0 · 시행일 2026년 9월 18일 · 로그인 전에 모든 조항을 읽어 주세요",
  "m0015": "본 이용 안내 및 면책 조항(이하 “본 성명”)은 본 소프트웨어 사용과 관련하여 사용자와 ARTEX 프로젝트 작성자 및 기여자 간에 적용되는 약정입니다. 사용 전에 모든 조항을 주의 깊게 읽고 이해해 주세요. 특히 굵은 글씨 또는 색상 영역으로 표시된 면책, 책임 제한 및 금지 조항을 확인해 주세요.",
  "m0016": "본 소프트웨어를 다운로드, 설치, 접속하거나 어떤 방식으로든 사용하면 본 성명 전체를 읽고 이해했으며 이에 구속되는 데 동의한 것으로 간주됩니다.",
  "m0017": "제1조 · 정의 및 오픈 소스 라이선스",
  "m0018": "ARTEX를 기반으로 하는 본 소프트웨어는 GNU Affero General Public License v3.0(AGPL-3.0)에 따라 공개된 오픈 소스 프로그램입니다. 해당 라이선스에 따라 사용, 복제, 수정 및 배포할 수 있습니다. 네트워크를 통해 제3자에게 제공하는 온라인 서비스를 포함한 파생 저작물도 AGPL-3.0으로 공개하고 사용자에게 완전한 해당 소스 코드를 제공해야 합니다. AGPL-3.0 전체 조항은 함께 제공되는 LICENSE 파일을 참조하세요.",
  "m0019": "제2조 · 허용된 사용 범위",
  "m0020": "본 소프트웨어는 개인 학습, 코드 연구, 보안 기술 원리 탐구 및 직접 구축한 로컬 격리 환경에서의 기술 검증만을 목적으로 합니다. 학습, 학술 연구, 코드 검토 등 비공격적이고 비파괴적인 용도로 사용해야 합니다. 본 조항에서 명시적으로 허용한 경우 외의 목적으로 사용할 수 없습니다.",
  "m0021": "제3조 · 금지 행위",
  "m0022": "허가 여부 또는 자산의 본인 소유 여부와 관계없이 웹사이트, 온라인 서비스, 타인이나 제3자의 네트워크 시스템을 스캔, 탐색, 악용 또는 공격하는 행위를 엄격히 금지합니다.",
  "m0023": "실제 침투 테스트, 공격·방어 활동, 레드팀·블루팀 훈련 또는 운영 환경에서 본 소프트웨어를 사용하는 행위를 엄격히 금지합니다.",
  "m0024": "불법 침입, 데이터 탈취, 갈취, 서비스 거부(DoS/DDoS) 또는 파괴적·범죄적 활동에 본 소프트웨어를 사용하는 행위를 엄격히 금지합니다.",
  "m0025": "본 소프트웨어 및 출력물의 저작권, 라이선스 또는 안전 안내를 삭제, 변조하거나 우회하는 행위를 엄격히 금지합니다.",
  "m0026": "거주 국가 또는 지역의 법률, 규정 및 규제 요건을 위반하는 행위를 엄격히 금지합니다.",
  "m0027": "제4조 · 지식재산권",
  "m0028": "본 소프트웨어의 저작권 및 관련 지식재산권은 프로젝트 작성자와 기여자에게 귀속되며, AGPL-3.0에서 정한 범위의 권리가 사용자에게 부여됩니다. 해당 라이선스에서 명시적으로 부여한 권리 외에 본 성명은 어떠한 명시적 또는 묵시적 권리도 부여하지 않습니다.",
  "m0029": "제5조 · 데이터 및 개인정보",
  "m0030": "본 소프트웨어는 자체 배포 가능한 오픈 소스 프로그램입니다. 작성자는 중앙 집중식 서비스를 운영하지 않으며 사용 데이터를 수집하거나 업로드하지 않습니다. 사용 중 생성, 처리 또는 접촉하는 모든 데이터는 사용자가 직접 통제하며 그 적법성과 보안에 책임을 집니다. 부적절한 데이터 처리로 발생하는 결과는 사용자가 부담합니다.",
  "m0031": "제6조 · 준법 및 법적 책임",
  "m0032": "사용자는 거주 국가 또는 지역의 사이버 보안, 데이터 보안, 개인정보 보호 및 컴퓨터 범죄에 관한 모든 법률을 준수해야 합니다. 중국 본토에서는 사이버보안법, 데이터보안법, 개인정보보호법 및 관련 사법 해석 등이 포함됩니다.",
  "m0033": "해당 법률 또는 본 성명을 위반하여 발생하는 모든 법적 책임과 결과는 사용자 본인이 독립적으로 부담하며, 본 소프트웨어 작성자 및 기여자와는 무관합니다.",
  "m0034": "제7조 · 면책 및 책임 제한",
  "m0035": "본 소프트웨어는 상품성, 특정 목적 적합성, 정확성 및 비침해 보증을 포함한 어떠한 명시적 또는 묵시적 보증 없이 “있는 그대로(AS IS)” 및 “이용 가능한 상태(AS AVAILABLE)”로 제공됩니다. 관련 법률이 허용하는 최대 범위에서 작성자 및 기여자는 적절한 사용 여부와 관계없이 사용 또는 사용 불능으로 발생하는 직접적, 간접적, 부수적, 특별 또는 결과적 손실에 책임을 지지 않습니다. 여기에는 데이터 손실, 시스템 손상, 업무 중단, 이익 손실 및 법적 분쟁 등이 포함됩니다.",
  "m0036": "제8조 · 조항 변경 및 해석",
  "m0037": "작성자는 법률 또는 프로젝트 발전에 따라 본 성명을 수시로 개정할 수 있습니다. 개정본은 프로젝트와 함께 공개되며 공표일부터 효력이 발생합니다. 계속 사용하면 개정 조항에 동의한 것으로 간주됩니다. 법률이 허용하는 범위에서 최종 해석권은 프로젝트 작성자에게 있습니다. 어느 조항이 무효로 판단되어도 나머지 조항의 효력은 유지됩니다.",
  "m0038": "모든 조항을 확인했습니다",
  "m0039": "확인하기 전에 조항 끝까지 스크롤하세요",
