  "m0738": "실행 시간(첫 단계 → 마지막 단계)",
  "m0739": "상호작용 가능",
  "m0740": "사용자가 이 의도를 삭제했습니다",
  "m0741": "(실행이 중지되고 플래너에 알렸습니다. 의도와 산출물은 보존되며 아래에서 기록을 볼 수 있습니다)",
  "m0742": "삭제 사유: ",
  "m0743": "이전 기록 불러오는 중…",
  "m0744": "활동 내역 불러오는 중…",
  "m0745": "불러오기 실패: ",
  "m0746": "아직 대화가 없습니다. 아래에서 메인 에이전트에 메시지를 보내 탐색 방향을 안내하거나 작업 흐름에 개입하세요.",
  "m0747": "아직 활동 기록이 없습니다.",
  "m0748": "메인 에이전트에 메시지 보내기",
  "m0749": "메인 에이전트가 실행 중입니다. /btw로 보조 질문을 하세요…",
  "m0750": "메인 에이전트에 메시지 입력. @로 취약점, 자산 등을 참조하세요…",
  "m0751": "현재 실행 중지",
  "m0752": "워커 #{p0}에 메시지 보내기",
  "m0753": "워커 #{p0}에 메시지 입력. @로 기록을 참조하고 실행 방향을 조정하세요…",
  "m0754": "현재 워커 일시 중지",
  "m0755": "메시지를 보내지 않고 실행 계속",
  "m0756": "바로 실행 계속",
  "m0757": "바로 계속",
  "m0758": "워커 삭제 #",
  "m0759": "영구 삭제",
  "m0760": "이 의도 및 하위 노드를 실제로 삭제합니다. 삭제 대상은",
  "m0761": "해당 의도만이 지지하는 노드이며",
  "m0762": "(고립 데이터를 방지하도록 말단까지 연쇄 삭제), 공유 노드, 목표 및 작업의 루트 사실은 유지합니다.",
  "m0763": "이 작업은 복구할 수 없습니다.",
  "m0764": "플래너가 삭제 알림을 받고 이를 반영하여 다시 계획합니다.",
  "m0765": "논리 삭제",
  "m0766": "이 의도를 삭제됨으로 표시하고 사유를 기록합니다. 의도 노드, 실행 기록, 등록된 사실 및 취약점은",
  "m0767": "모두 유지됩니다",
  "m0768": ". 플래너는 사용자 삭제 및 사유를 전달받아 이를 반영하여 다시 계획합니다.",
  "m0769": "데이터 및 추적 가능성 유지",
  "m0770": "연쇄 삭제, 복구 불가",
  "m0771": "삭제 사유(필수)",
  "m0772": "의도 삭제 이유를 설명하세요. 예: 잘못된 방향 / 대상 무효 / 다른 의도와 중복…",
  "m0773": "뒤로",
  "m0774": "영구 삭제",
  "m0775": "새 세션을 시작할까요?",
  "m0776": "현재 세션은 보관되며 언제든 다시 전환할 수 있습니다. 메인 에이전트는 새 문맥으로 계속합니다. 작업 그래프, 자산 및 목표는 유지됩니다.",
  "m0777": "시작 중…",
  "m0778": "새 세션 시작",
  "m0779": "세션",
  "m0780": "탐색 경로",
  "m0781": "알림 보드",
  "m0782": "자산 테스트 범위 그래프",
  "m0783": "차단 승인",
