  "m0790": "작업이 종료되었습니다. 변경 사항은 이후 메인 에이전트 대화에만 적용됩니다.",
  "m0791": "저장 후 초기화",
  "m0792": "저장 중",
  "m0793": "LLM 프로필을 업데이트하고 할당량 부족으로 차단된 의도 {p0}개를 복구했습니다",
