  "m0812": "작업 보관",
  "m0813": "작업 보관 #",
  "m0814": "작업 그래프, 연결된 기록, 전용 자산 및 트래픽, 작업 파일과 LLM 기록을 압축하여 장기 보관합니다. 보관 완료 후 작업 목록의 “보관됨” 탭에서 복원할 수 있습니다.",
