  "m0949": "현재 작업 디렉터리의 업로드 파일, 명령 출력 및 기타 산출물을 삭제합니다.",
  "m0950": "연결된 취약점",
  "m0951": "이 작업에서 생성한 독립적인 취약점 기록 및 보고서를 영구 삭제합니다.",
  "m0952": "LLM 요청/응답 기록",
  "m0953": "이 작업에 기록된 LLM 요청, 응답, 토큰 및 오류 상세를 영구 삭제합니다.",
