  "m1004": "분류 관리",
  "m1005": "작업 분류 관리",
  "m1006": "분류는 작업 필터와 보관 정리에 사용됩니다. 변경해도 작업 실행에는 영향을 주지 않습니다. 분류를 삭제하면 해당 작업은 미분류로 이동합니다.",
