  "m1010": "현재 {p0}개 작업이 이 분류를 사용합니다. 이름을 변경하면 작업 목록에도 반영됩니다.",
  "m1011": "생성 후 작업 생성 및 작업 목록 필터에서 사용할 수 있습니다.",
