  "m1020": "분류 삭제: “",
  "m1021": "이름 없는 분류",
  "m1022": "분류를 삭제하면 해당 분류의",
  "m1023": "개 작업이 미분류로 이동합니다. 작업 데이터는 삭제되지 않습니다.",
  "m1024": "설명과 목표를 입력하세요",
  "m1025": "최대 {p0}개 원본 작업을 연결할 수 있습니다",
  "m1026": "작업을 생성했습니다",
  "m1027": "생성 실패: ",
  "m1028": "새 작업",
  "m1029": "테스트 대상과 목표를 입력하세요. 필요하면 고급 설정을 펼치세요.",
  "m1030": "이름(선택 사항)",
  "m1031": "알아보기 쉬운 작업 이름을 입력하세요. 예: Acme 웹사이트 평가",
  "m1032": "필터와 보관 정리에 사용할 분류 하나를 선택할 수 있습니다. 에이전트 실행에는 영향을 주지 않습니다.",
  "m1033": "테스트 대상 및 배경. 예: example.com 사이트 테스트",
  "m1034": "파일 {p0}개를 업로드했습니다. 설명 끝에 절대 경로를 추가했습니다(편집 가능)",
  "m1035": "여러 파일을 선택할 수 있습니다. 워커가 Read/Bash로 열 수 있도록 설명에 절대 경로를 추가합니다",
  "m1036": "달성할 결과. 예: 관리자 접근 권한 또는 서버 접근 권한 확보",
  "m1037": "연결된 작업",
  "m1038": "최대 연결 수:",
  "m1039": "개 작업. 선택한 작업의 영구 블랙보드, 자산 범위 및 관련 트래픽을 실시간 읽기 전용으로 상속합니다. 새 작업은 독립적인 블랙보드에 기록합니다.",
  "m1040": "기업 자산 범위 연결",
  "m1041": "작업 생성 시 선택한 기업의 기존 자산을 테스트 자산에 추가합니다. 도메인, IP, CIDR, ICP 및 기업 키워드는 에이전트의 범위 문맥으로 제공됩니다. 의도를 자동으로 생성하거나 실행 목표를 강제로 변경하지 않습니다.",
  "m1042": "작업별 자산 차단 / 허용 규칙(선택 사항)",
  "m1043": "전역 규칙에 저장되지 않고 현재 작업에만 적용됩니다. 먼저 전역 규칙을 포함한 차단 규칙을 확인하며 일치하면 테스트를 금지합니다. 차단 규칙에 일치하지 않고 작업의 허용 규칙이 있다면 허용 규칙에 일치해야 합니다. 허용 규칙이 없으면 허용 목록은 적용하지 않습니다.",
  "m1044": "LLM 프로필 체인",
  "m1045": "목록 순서대로 장애 전환합니다. 첫 번째 항목이 현재 프로필이며 할당량 부족이 명확할 때만 다음 항목으로 전환합니다.",
  "m1046": "고급 설정",
  "m1047": "시간 제한 · 하트비트 · 첫 의도",
  "m1048": "작업 시간 제한(분, 선택 사항)",
  "m1049": "비우면 제한 없음",
  "m1050": "제한 시간에 도달하면 에이전트 결과 기록과 플래너 최종 판단을 통해 정상 마무리를 시작합니다. 작업은 시간 초과 상태로 종료됩니다.",
  "m1051": "플래너 하트비트(분)",
  "m1052": "기본값: 10",
  "m1053": "마지막 계획 종료 또는 작업 시작 이후 다른 트리거 없이 이 시간이 지나면 계획 단계를 자동으로 시작하여 정체를 복구하고 실행 중인 워커를 감독합니다. 최소 10분입니다.",
  "m1054": "첫 의도 바로 배정(설명 + 목표)",
  "m1055": "생성 즉시 설명과 목표를 하나의 의도로 배정하여 워커가 첫 계획을 기다리지 않고 시작합니다. 완료 후 플래너가 결과를 판단하고 보완합니다. 워커 하나로 해결하는 경우가 많은 CTF와 같은 상황에 권장합니다. 끄면 계획 후 실행하는 기본 흐름을 따릅니다.",
  "m1056": "자산 테스트 범위 기능",
  "m1057": "기본적으로 켜져 있으며 테스트 범위를 계산·표시하고 그래프에 진행률을 표시하며 테스트 범위를 자동 누적합니다. 끄면 테스트 범위 및 그래프 진행률을 표시하지 않고 에이전트에 범위 도구를 제공하지 않습니다. 연결된 기업 자산 범위에는 영향을 주지 않습니다.",
  "m1058": "생성 중",
