  "m1102": "메시지 불러오는 중…",
  "m1103": "전체 영구 삭제:",
  "m1104": "개 트래픽 기록(요청·응답 원문 포함). 현재 필터와 관계없이 삭제하며 되돌릴 수 없습니다. 취약점에 연결된 트래픽 증거는 별도 증거 저장소에 보관되어 영향을 받지 않습니다.",
  "m1105": "비운 후 저장소를 압축 정리하여 인덱스가 사용하던 디스크 공간을 반환합니다. 이 과정에서 트래픽 기록이 잠시 중단됩니다.",
  "m1106": "개 대상 (",
