  "m1135": "기본 제공",
  "m1136": "(설명 없음)",
  "m1137": "에이전트 삭제: “",
  "m1138": "프롬프트, 변수, 표시 설정 및 도구 연결도 함께 삭제됩니다. 되돌릴 수 없습니다.",
  "m1139": "“{p0}” 에이전트를 생성했습니다",
  "m1140": "새 에이전트",
  "m1141": "새 사용자 지정 에이전트",
  "m1142": "대화형 도우미를 생성합니다. 키는 내부 식별자로 생성 후 변경할 수 없습니다. 이름과 설명은 도우미를 구분하는 데 사용됩니다.",
  "m1143": "예: research_helper",
  "m1144": "소문자로 시작하고 소문자, 숫자, 밑줄만 사용하세요",
  "m1145": "예: 연구 도우미",
  "m1146": "이 에이전트의 역할을 한 문장으로 설명하세요",
