  "m1168": "도메인, IP, URL의 정확한/부분 일치 및 CIDR 서브넷을 지원합니다. 기본 자산 차단 규칙은 정부(.gov / .gov.cn) 및 교육(.edu / .edu.cn) 도메인에 적용됩니다.",
