  "m1492": "줄마다 KEY=VALUE, 예: Authorization=Bearer xxx",
  "m1493": "요청 본문 템플릿",
  "m1494": "비우면 기본 템플릿을 사용합니다. 변수: {{.Title}} {{.Batch}} {{.Count}} {{.HomeURL}} {{.SentAt}}, ",
  "m1495": "range .Items 내의 .Name/.VulnClass/.Severity/.Summary/.Assets/.DetailURL/.StatusLabel.",
  "m1496": "문자열 삽입 시 {{.Xxx}} 대신 {{json .Xxx}}를 사용하세요. 그렇지 않으면 제목의 따옴표가 JSON 형식을 깨뜨립니다.",
  "m1497": "API URL",
  "m1498": "비우면 공식 URL을 사용합니다. 자체 Bot API 역방향 프록시를 사용할 때 입력하세요",
  "m1499": "SMTP 서버",
